    f <= SURFACE_HOLD
      ? interpolate(f, [5, SURFACE_HOLD], [0, 1000], {easing: Easing.inOut(Easing.cubic)})
      : f <= BOTTOM_FRAME
      ? interpolate(f, [SURFACE_HOLD, BOTTOM_FRAME], [1000, 10994], {easing: Easing.inOut(Easing.cubic)})
