      <div style={{
        position: 'absolute', width: '100%', height: '100%', opacity: gridOpacity,
        backgroundImage: `linear-gradient(${grid} 1px, transparent 1px), linear-gradient(90deg, ${grid} 1px, transparent 1px)`,
        backgroundSize: '60px 60px'
